from google.cloud import documentai_v1 as documentai
from google.protobuf import json_format

def extract_table_layout(document_content: bytes) -> dict:
    """
    Extract table cells and row structure from a document using Google Document AI.

    Args:
        document_content: Raw bytes of the document (PDF or image)

    Returns:
        Dictionary containing extracted table structure with cells and rows
    """
    # Initialize the Document AI client
    client = documentai.DocumentProcessorServiceClient()

    # Replace with your Document AI processor ID and location
    processor_id = "YOUR_PROCESSOR_ID"
    location = "us"  # e.g., "us", "eu"
    project_id = "YOUR_PROJECT_ID"

    # Construct the full processor path
    processor_path = client.processor_path(project_id, location, processor_id)

    # Configure the request
    request = documentai.ProcessRequest(
        name=processor_path,
        raw_document=documentai.RawDocument(content=document_content, mime_type="application/pdf")
    )

    # Process the document
    response = client.process(request=request)

    # Convert to a dictionary for easier processing
    document = json_format.MessageToDict(response.document)

    tables = []

    # Iterate through all pages
    for page in document.get("pages", []):
        for entity in page.get("entities", []):
            if entity.get("type") == "TABLE":
                table_data = {
                    "rows": [],
                    "cells": []
                }

                # Process table entities
                for table_entity in entity.get("properties", []):
                    if table_entity.get("name") == "table":
                        # Process rows
                        for row_property in table_entity.get("properties", []):
                            if row_property.get("name") == "row":
                                row_data = {
                                    "cells": []
                                }

                                # Process cells in this row
                                for cell_property in row_property.get("properties", []):
                                    if cell_property.get("name") == "cell":
                                        cell_content = ""

                                        # Extract text content from the cell
                                        if "text" in cell_property:
                                            cell_content = cell_property["text"]
                                        elif "layout" in cell_property and "text" in cell_property["layout"]:
                                            cell_content = cell_property["layout"]["text"]

                                        row_data["cells"].append({
                                            "content": cell_content,
                                            "layout": cell_property.get("layout", {})
                                        })

                                table_data["rows"].append(row_data)

                tables.append(table_data)

    return {"tables": tables}
